package model;

public class Elyra extends Personagem {
    public Elyra(){super("Elyra",105,55,new Atributos(4,3,5,3,6,4));definirNivel(2);Equipamento arco=new Equipamento("Arco de Madeira Reforcado","Arma","Comum","Arqueira Arcana",40,1,0,0,0,0,0);Equipamento armadura=new Equipamento("Traje de Cacadora","Armadura","Comum","Arqueira Arcana",45,0,0,0,0,1,0);equiparDireto(arco);equiparDireto(armadura);}
    public boolean habilidade(Grupo grupo,Inimigo[] inimigos){while(true){System.out.println("\n"+Cores.magia("=== HABILIDADES DE ELYRA ==="));System.out.println("1 - Flecha Arcana (6 mana)");System.out.println("2 - Flecha de Gelo (8 mana)");System.out.println("0 - Voltar");int op=Entrada.lerInt("Escolha: ");if(op==0)return false;if(op!=1&&op!=2){System.out.println(Cores.aviso("Opcao invalida. Escolha 1, 2 ou 0."));continue;}int custo=op==1?6:8;if(mana<custo){System.out.println(Cores.aviso("Mana insuficiente. Sao necessarios "+custo+" pontos."));continue;}Inimigo alvo=Batalha.escolherInimigo(inimigos);if(alvo==null)continue;usarMana(custo);int dano=op==1?getForca()*2+getInteligencia()*2+random.nextInt(5)-2:getInteligencia()*3+random.nextInt(4)-2;Batalha.AtaqueResultado r=Batalha.calcularAtaque(this,alvo,dano);if(r.acertou)System.out.println(Cores.magia((op==1?"Flecha Arcana":"Flecha de Gelo")+" causou "+r.dano+" de dano!"));else System.out.println(Cores.aviso("Elyra errou o ataque!"));return true;}}
}
